effect.shader:
float gmLum(vec3 c){ return dot(c, vec3(0.2126, 0.7152, 0.0722)); }
void main(){
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
float aspect = max(getTexSize(inputImg.size).x / max(getTexSize(inputImg.size).y, 1.0), 0.5);
vec2 c = vec2(rayCX * 0.01, rayCY * 0.01);
vec2 duv = (uv - c) * vec2(1.0, aspect);
vec2 stepV = -duv * rayLength * 0.25 / 24.0;
float illum = 1.0;
float acc = 0.0;
vec3 accC = vec3(0.0);
vec2 sp = uv;
for (int i = 0; i < 24; i++) {
sp += stepV / vec2(1.0, aspect);
vec3 s = texture2DCv(inputImg.texture, clamp(sp, 0.0, 1.0)).rgb;
float m = smoothstep(rayThresh, rayThresh + 0.18, gmLum(s));
accC += s * m * illum;
acc += m * illum;
illum *= rayDecay;
}
float w = rayDensity * 0.9;
vec3 rays = accC * w * rayBright;
vec3 col = src.rgb;
col += rayTint.rgb * rays * 0.55;
if (!hideSource) {
float lm = smoothstep(rayThresh, rayThresh + 0.18, gmLum(src.rgb));
col += src.rgb * lm * 0.4;
}
gl_FragColor = vec4(col * src.a, src.a);
}
